    "lines": [
     {
      "en": "Calm introductions.",
      "fr": "Des rencontres calmes.",
      "kind": "title"
     },
     {
      "en": "Let the dog approach the child by choice, calmly, and keep first meetings short.",
      "fr": "Laissez le chien s’approcher de l’enfant de lui-même, calmement, et gardez les premières rencontres courtes.",
      "kind": "body"
     }
    ]
